def fill(pattern, letters):
    it = iter(letters)
    out = "".join(next(it) if ch == "_" else ch for ch in pattern)
    assert next(it, None) is None
    return out

def block(s):
    # shortest period p (a full block fits at least twice) with s[i] == s[i+p] everywhere
    for p in range(1, len(s) // 2 + 1):
        if all(s[i] == s[i + p] for i in range(len(s) - p)):
            return s[:p]
    return None

def solve(pattern, options):
    pattern = pattern.replace(" ", "")
    fits = {k: block(fill(pattern, v)) for k, v in options.items()
            if len(v) == pattern.count("_")}
    return [k for k, b in fits.items() if b]

