from fractions import Fraction as F

def diffs(s):
    return [b - a for a, b in zip(s, s[1:])]

def diff_pattern(d):
    """Name the pattern of the differences: constant, AP, GP, or None."""
    if len(set(d)) == 1:
        return "constant"
    if len(set(diffs(d))) == 1:
        return "AP"
    if 0 not in d and len({F(b, a) for a, b in zip(d, d[1:])}) == 1:
        return "GP"
    return None

def solve(terms, options):
    good = []
    for k, v in options.items():
        s = [v if t is None else t for t in terms]
        if diff_pattern(diffs(s)):
            good.append(k)
    return good

