def is_prime(n):
    return n > 1 and all(n % p for p in range(2, int(n ** 0.5) + 1))

PRIMES = [p for p in range(2, 200) if is_prime(p)]

def consecutive_primes(d):
    """Differences are consecutive primes, ascending or descending."""
    a = [abs(x) for x in d]
    if not all(x in PRIMES for x in a):
        return False
    idx = [PRIMES.index(x) for x in a]
    steps = {j - i for i, j in zip(idx, idx[1:])}
    return steps in ({1}, {-1}) and len({x > 0 for x in d}) == 1

def solve(terms, options):
    good = []
    for k, v in options.items():
        s = [v if t is None else t for t in terms]
        if consecutive_primes([b - a for a, b in zip(s, s[1:])]):
            good.append(k)
    return good

