def root(n, k):
    r = round(abs(n) ** (1 / k))
    return next((x for x in (r - 1, r, r + 1) if x ** k == n), None)

def bases(seq, powers):
    """Bases b with seq[i] = b**powers[i], or None."""
    out = [root(x, p) for x, p in zip(seq, powers)]
    return None if None in out else out

def is_ap(b):
    return len({y - x for x, y in zip(b, b[1:])}) == 1

def fits(s):
    d = [b - a for a, b in zip(s, s[1:])]
    for seq in (s, d):  # terms first, then differences
        for pw in ([2] * len(seq), [3] * len(seq), [3 if i % 2 == 0 else 2 for i in range(len(seq))]):
            b = bases(seq, pw)
            if b and is_ap(b):
                return True
    return False

def solve(terms, options):
    good = []
    for k, v in options.items():
        vals = v if isinstance(v, tuple) else (v,)
        it = iter(vals)
        s = [next(it) if t is None else t for t in terms]
        if fits(s):
            good.append(k)
    return good

