def ap(s):
    return len({b - a for a, b in zip(s, s[1:])}) <= 1

def split_fits(s):
    return ap(s[0::2]) and ap(s[1::2])

def alt_ops_fits(s):
    """Operations alternate: the odd steps share one (x k or + k) and so do the even steps."""
    def same_op(pairs):
        adds = {b - a for a, b in pairs}
        mults = {b / a for a, b in pairs if a} if all(a for a, _ in pairs) else set()
        return len(adds) == 1 or len(mults) == 1
    steps = list(zip(s, s[1:]))
    return same_op(steps[0::2]) and same_op(steps[1::2])

def solve(terms, options, test):
    good = []
    for k, v in options.items():
        s = [v if t is None else t for t in terms]
        if test(s):
            good.append(k)
    return good

